// Gateway (edge node) heartbeat, and what this appliance reports about itself.
//
// WHAT MAKES THE GATEWAY SHOW 'ONLINE'. The ingestion daemon stamps gateways.last_heartbeat on
// every node-level message -- NBIRTH, NDATA or NDEATH -- and the dashboard derives staleness from
// it at read time with a 90s threshold. Beating every 30s allows three missed beats before this
// appliance is reported STALE.
//
// PAYLOAD IS JSON, NOT PROTOBUF, and that is a supported encoding rather than a shortcut: the
// ingestion daemon's parse_sparkplug_payload() tries protobuf first and falls back to this shape.
// It is what the platform's own simulator publishes. If you later add a protobuf encoder, nothing
// else in this flow has to change -- the topic is what identifies the asset.

const GROUP = '__SPARKPLUG_GROUP__';
const NODE  = '__SPARKPLUG_ID__';
const type  = msg.payload;   // 'NBIRTH' or 'NDATA'

// UPTIME FROM FLOW CONTEXT, NOT process.uptime().
//
// A Node-RED function node runs in a SANDBOX with no `process` global. `process.uptime()` is not a
// syntax error and is not caught at deploy time -- it throws at the first tick:
//
//     ReferenceError: process is not defined
//
// and because the throw happens BEFORE msg is returned, nothing is ever published. The broker node
// connects, the editor looks healthy, and the gateway sits in AWAITING_BIRTH forever with the only
// evidence in the appliance's own logs. Verified against Node-RED 5.0.2.
//
// The first tick records its own start instead, which is the process start for every practical
// purpose here -- this node runs on the same 'on start' inject that produces the NBIRTH.
let startedAt = context.get('startedAt');
if (!startedAt) {
    startedAt = Date.now();
    context.set('startedAt', startedAt);
}

// ONE SEQ FOR THE WHOLE EDGE NODE is stamped by **store and forward** as each message is
// published, so a message it buffers or drops during an outage takes no number.

// An NBIRTH invalidates every device birth under this node, so "publish by exception" re-births
// each device, at its last values, on its next refresh.
if (type === 'NBIRTH') {
    const devices = flow.get('rbe') || {};
    for (const d of Object.values(devices)) d.born = false;
    flow.set('rbe', devices);
}

// ---------------------------------------------------------------------------------------------
// METRIC ENCODING: `datatype` PLUS A TYPED VALUE FIELD, NOT `{ type, value }`.
//
// The daemon's JSON reader takes a metric's type only from `datatype`. It reads a bare `value` by
// what the JSON holds and ignores `type`, so `{ type, value }` would arrive untyped.
//
// BYTE COUNTS GO AS `double_value`. Sparkplug's `int_value` is a 32-bit field, smaller than the
// memory and disk figures below, and the daemon drops a metric whose value does not fit its field.
// A double carries integers exactly to 2^53, nine petabytes.
// ---------------------------------------------------------------------------------------------
const num = (name, value) => ({ name, datatype: 10, double_value: Number(value) });
const str = (name, value) => ({ name, datatype: 12, string_value: String(value) });

const metrics = [
    // Read by ingestion's process_node_message(): a Gateway_Status string metric OVERRIDES the
    // status implied by the message type. Sending it explicitly means this appliance says what it
    // thinks its own state is rather than having it inferred -- which, encoded correctly, it now
    // actually does.
    str('Gateway_Status', 'ONLINE'),
    num('Uptime_s', Math.floor((Date.now() - startedAt) / 1000)),
];

// ---------------------------------------------------------------------------------------------
// THE BUNDLE THIS APPLIANCE RUNS, resolved by bootstrap.mjs and handed over in /data/gateway.env.
//
// It is not computed here because it CANNOT be: the function sandbox has no `process` to read an
// argv from, no `require`, and settings.js declares `functionGlobalContext: {}` on purpose. It is
// fixed for the life of an enrolment, which is what an environment variable can express.
//
// OMITTED RATHER THAN SENT EMPTY: a blank Agent_Version would overwrite the one recorded at
// enrolment with nothing. The daemon refuses it, but not sending it is the honest form of
// "not known here".
// ---------------------------------------------------------------------------------------------
const agentVersion = env.get('GATEWAY_AGENT_VERSION');
if (agentVersion) metrics.push(str('Agent_Version', agentVersion));

// ---------------------------------------------------------------------------------------------
// WHEN THE ROOT THIS APPLIANCE TRUSTS EXPIRES, from the cache the `read ca.json` branch fills.
//
// FROM A FILE BECAUSE IT CHANGES WITHOUT AN ENROLMENT. aber-gateway-converge installs the bundle
// the platform publishes and restarts this container; an environment value would be the enrolment
// root's date for the life of the appliance, which is exactly the case the dashboard needs to see
// move. The platform holds its own root's expiry beside this one, so the two together say whether
// this appliance has been given a re-issued root yet.
// ---------------------------------------------------------------------------------------------
const ca = flow.get('ca');
if (ca && Number.isFinite(ca.not_after_ms)) metrics.push(num('Cert_Expires_At', ca.not_after_ms));



// ---------------------------------------------------------------------------------------------
// THE FLOW THIS APPLIANCE LAST DEPLOYED, from the cache the `read deployed.json` branch fills.
//
// flow-sync.mjs records the SHA-256 of every flow it deploys in /data/gitops/deployed.json, and
// bootstrap.mjs records the enrolment flow there in the same shape. The platform holds the
// SHA-256 of flows.json at the head of main, so equal hashes mean this appliance has deployed
// what was approved and different ones mean it has not yet. Read from that file rather than from
// gateway.env because a reload does not re-source the environment: an environment value would
// be the enrolment flow's hash for the life of the container.
// ---------------------------------------------------------------------------------------------
const deployed = flow.get('deployed');
if (deployed && deployed.flow_sha256) metrics.push(str('Flow_Hash', deployed.flow_sha256));

// ---------------------------------------------------------------------------------------------
// HOST METRICS, from the cache the `poll host metrics` branch fills every 60s.
//
// READ FROM A CACHE RATHER THAN FETCHED HERE, AND THAT IS THE POINT. Chaining the HTTP request
// into this path would make the heartbeat depend on node_exporter answering: a collector that is
// down, or merely slow, would stop the heartbeat -- and a gateway that stops beating is reported
// STALE and then OFFLINE. A disk-usage collector must never be able to take a gateway off the
// board. Cached, its failure costs three metrics and nothing else.
//
// STALE READINGS ARE DROPPED, NOT REPUBLISHED. Past five minutes the cached numbers stop being
// sent rather than being repeated forever. The platform keeps the last value it received (these
// are columns, not a time series -- see migration 0035), so the reading on the page is always one
// this appliance actually took.
// ---------------------------------------------------------------------------------------------
const HOST_MAX_AGE_MS = 5 * 60 * 1000;
const host = flow.get('host');
if (host && Number.isFinite(host.at) && (Date.now() - host.at) < HOST_MAX_AGE_MS) {
    if (Number.isFinite(host.load1)) metrics.push(num('Load_1m', host.load1));
    if (Number.isFinite(host.memAvailable)) metrics.push(num('Mem_Available_Bytes', host.memAvailable));
    if (Number.isFinite(host.diskFree)) metrics.push(num('Disk_Free_Bytes', host.diskFree));
}

// ---------------------------------------------------------------------------------------------
// AN NBIRTH DECLARES EVERY METRIC THIS NODE WILL EVER SEND (tck-id-topics-nbirth-metric-reqs), so
// one not known yet is declared null rather than left out; an NDATA sends only what is known.
// Store and forward adds bdSeq, Node Control/Rebirth and the outage report.
// ---------------------------------------------------------------------------------------------
const DECLARED = [
    ['Agent_Version', 12], ['Cert_Expires_At', 10], ['Flow_Hash', 12],
    ['Load_1m', 10], ['Mem_Available_Bytes', 10], ['Disk_Free_Bytes', 10],
];
if (type === 'NBIRTH') {
    for (const [name, datatype] of DECLARED) {
        if (!metrics.some((m) => m.name === name)) metrics.push({ name, datatype, is_null: true });
    }
}

msg.topic = `spBv1.0/${GROUP}/${type}/${NODE}`;
msg.payload = { timestamp: Date.now(), metrics };
// After an NBIRTH, "publish by exception" re-births every device at its last values now rather
// than at its next refresh: the second output. A host that asked for the rebirth then has the
// whole node declared again in one burst, which is what it asked for.
return [msg, type === 'NBIRTH' ? { payload: 'refresh' } : null];

// A reading from an example machine, sent to "publish by exception" the way your own flow would.
//
// ZERO-TOUCH ONBOARDING. The first reading births the device, which puts it in the dashboard's
// quarantine queue; its data is dropped until an operator approves it there, choosing its name
// and cell. Nothing is pre-registered and nothing here calls the platform's API.
//
// Click again: only the metrics that moved are published.
//
// CHANGE THIS to whatever your machine should be called.
const DEVICE_ID = 'press-01';

const n = (context.get('n') || 0) + 1;
context.set('n', n);

msg.payload = {
    device: DEVICE_ID,
    metrics: {
        'Properties/Manufacturer': 'Example Machine Co',            // never moves
        Running: true,                                              // never moves
        CycleCount: n,                                              // moves on every click
        Temperature: Math.round((20 + Math.random() * 2) * 10) / 10, // moves on most clicks
    },
};
return msg;

// Device readings in, Sparkplug out, publishing only what changed.
//
// IN   msg.payload = { device: 'press-01', metrics: { Temperature: 21.4, Running: true } }
//      with an optional payload.timestamp in epoch ms, msg.payload === 'refresh', or
//      msg.payload = { rebirth: 'press-01' } from a rebirth request.
// OUT  a DBIRTH the first time a device or a metric name is seen, then DDATA carrying only the
//      metrics that moved, each with the reading's timestamp.
//
// A number is published when it moves by more than its DEADBAND below: `absolute` units or
// `percent` of the last published value, whichever is larger. None is set, so any change is
// published; set one for a noisy analogue signal. Booleans and strings are published on any change.
//
// THE REFRESH is the proof of life. Every REFRESH_S the inject below republishes every metric at
// its last value: a steady machine is then told apart from a dead sensor, and the platform, which
// marks a device OFFLINE after 300 s without data (DEVICE_OFFLINE_TIMEOUT_SECONDS), keeps it
// ONLINE. Keep the inject's interval well under 300 s.
const DEADBAND = {
    // Temperature: { absolute: 0.2 },
    // Pressure: { percent: 0.5 },
};

const GROUP = '__SPARKPLUG_GROUP__';
const NODE  = '__SPARKPLUG_ID__';

// Datatypes: 10 double, 11 boolean, 12 string. Counters travel as doubles: Sparkplug's int_value
// is a 32-bit field, and a double holds integers exactly to 2^53.
const DATATYPE = { number: 10, boolean: 11, string: 12 };
const FIELD = { 10: 'double_value', 11: 'boolean_value', 12: 'string_value' };

const devices = flow.get('rbe') || {};
const out = [];

const encode = (name, m, timestamp) => ({ name, datatype: m.datatype, timestamp, [FIELD[m.datatype]]: m.value });

// Store and forward stamps the edge node's seq as it publishes. A refresh restates values already
// sent, so it is marked: during an outage it is dropped rather than buffered.
function publish(device, type, metrics, timestamp, refresh) {
    out.push({
        topic: `spBv1.0/${GROUP}/${type}/${NODE}/${device}`,
        payload: { timestamp, metrics },
        refresh: Boolean(refresh),
    });
}

// Every metric the device will publish, declared at its last value.
function birth(device, d, timestamp) {
    const metrics = [{ name: 'Device Control/Rebirth', datatype: 11, boolean_value: false, timestamp }];
    for (const [name, m] of Object.entries(d.metrics)) metrics.push(encode(name, m, timestamp));
    publish(device, 'DBIRTH', metrics, timestamp);
    d.born = true;
}

// Compared with the last PUBLISHED value, so a slow drift inside the band is still published
// once it has moved far enough in total.
function moved(name, before, value) {
    if (!before) return true;
    if (typeof value !== 'number') return value !== before.value;
    const band = DEADBAND[name];
    if (!band) return value !== before.value;
    const limit = Math.max(band.absolute || 0, Math.abs(before.value) * (band.percent || 0) / 100);
    return Math.abs(value - before.value) > limit;
}

if (msg.payload === 'refresh') {
    const now = Date.now();
    for (const [device, d] of Object.entries(devices)) {
        const names = Object.keys(d.metrics);
        if (!names.length) continue;
        if (!d.born) birth(device, d, now);
        else publish(device, 'DDATA', names.map((name) => encode(name, d.metrics[name], now)), now, true);
    }
    flow.set('rbe', devices);
    node.status({ text: `refreshed ${Object.keys(devices).length} device(s)` });
    return out.length ? [out] : null;
}

// A host asked for one device's birth again (DCMD Device Control/Rebirth).
if (msg.payload && typeof msg.payload.rebirth === 'string') {
    const d = devices[msg.payload.rebirth];
    if (!d || !Object.keys(d.metrics).length) {
        node.warn(`rebirth requested for ${msg.payload.rebirth}, which has published nothing here`);
        return null;
    }
    birth(msg.payload.rebirth, d, Date.now());
    flow.set('rbe', devices);
    return [out];
}

const { device, metrics } = msg.payload || {};
const timestamp = Number(msg.payload && msg.payload.timestamp) || Date.now();
if (typeof device !== 'string' || !/^[^/+#\s]+$/.test(device) || !metrics || typeof metrics !== 'object') {
    node.warn('ignored: expected msg.payload = { device: "<id>", metrics: { <name>: <value> } }');
    return null;
}

const d = devices[device] || (devices[device] = { born: false, metrics: {} });
const changed = [];
let rebirth = false;
for (const [name, value] of Object.entries(metrics)) {
    const datatype = DATATYPE[typeof value];
    if (!datatype || (datatype === 10 && !Number.isFinite(value))) {
        node.warn(`ignored ${device}/${name}: a number, boolean or string is expected`);
        continue;
    }
    const before = d.metrics[name];
    // A name or a type the last birth did not declare needs a new birth before DDATA may carry it.
    if (!before || before.datatype !== datatype) rebirth = true;
    if (moved(name, before, value)) {
        d.metrics[name] = { value, datatype };
        changed.push(encode(name, d.metrics[name], timestamp));
    }
}

if (!d.born || rebirth) birth(device, d, timestamp);
else if (changed.length) publish(device, 'DDATA', changed, timestamp);

flow.set('rbe', devices);
node.status({ text: `${device}: ${changed.length} of ${Object.keys(metrics).length} published` });
return out.length ? [out] : null;

// Store and forward: the Sparkplug session, and everything this appliance publishes.
//
// A SPARKPLUG 3.0.0 EDGE NODE CONFIGURED WITH A PRIMARY HOST, when /data/gateway.env names one
// (GATEWAY_PRIMARY_HOST_ID). This node owns the connection: the broker node does not connect on
// its own, and every CONNECT carries an NDEATH with the next bdSeq, as the Last Will and as the
// message published before an intentional disconnect. The node births only once the primary
// host's STATE says it is online. When a valid offline STATE arrives it disconnects (publishing
// the NDEATH) and connects again, as the specification requires. Without a primary host it births
// as soon as it is connected.
//
// WHILE NO READING CAN BE DELIVERED -- the broker is unreachable, or the node is waiting for the
// host -- device readings are appended to segment files under BUFFER_DIR. After the next NBIRTH
// they are replayed, oldest segment first and in timestamp order within it, with is_historical set
// on every metric, so the platform files each at the time it was read. Births and heartbeats are
// never buffered: they state the present, and every new session births everything again.
//
// THE LOSS IS MEASURED WHETHER OR NOT ANYTHING IS BUFFERED. After an outage the next three node
// messages carry Outage/Started_At, Outage/Ended_At, Outage/Readings_Buffered,
// Outage/Readings_Dropped and Outage/Buffering, which every NBIRTH declares (null when there is
// nothing to report). The platform counts them per gateway and alerts when readings were dropped.
// Readings_Buffered is what was written to the buffer during the outage; Readings_Dropped is what
// the outage cost: never buffered, evicted from a full buffer, too old to keep, or a torn line.
//
// THE WIRE IS SPARKPLUG B PROTOBUF, encoded here: the rest of the flow builds plain objects. Every
// metric gets a timestamp, and one seq is stamped here for the whole edge node as each message is
// published, so a buffered or dropped message takes no number.
//
// HOW THE FILES ARE WRITTEN. A function node has no `fs`, so three core `file` nodes do the
// writing. A segment is append-only JSON lines, one message a line: a line torn by a power cut
// fails to parse and is counted as dropped, and every line before it is whole. The index of
// segments, and the bdSeq, alternate between two state files carrying a generation number, and the
// newer one that parses is read at start, so a torn write costs at most the last few seconds of
// bookkeeping. Nothing is fsync'd: a power cut can lose what the kernel had not yet written.
//
// CHANGE THESE to suit the appliance. MAX_BYTES bounds the disk the buffer may use; when it is
// full the OLDEST segment is dropped and its readings counted. MAX_AGE_DAYS matches the platform's
// window for historical readings (ingestion.historicalMaxAgeSeconds); older ones would be refused.
// BUFFER_ENABLED = false keeps nothing and still reports what each outage cost.
const BUFFER_ENABLED = true;
const MAX_BYTES = 256 * 1024 * 1024;
const MAX_AGE_DAYS = 7;
// A fleet replays at once after a platform outage, and together it must stay under what the
// historian writes (ingestion/README.md, "Loss model"): fifty readings a second per appliance,
// after a random delay of up to REPLAY_START_JITTER_S.
const REPLAY_READINGS_PER_SECOND = 50;
const REPLAY_START_JITTER_S = 30;

const PRIMARY_HOST_ID = String(env.get('GATEWAY_PRIMARY_HOST_ID') || '');
const NDEATH_TOPIC = 'spBv1.0/__SPARKPLUG_GROUP__/NDEATH/__SPARKPLUG_ID__';
const BUFFER_DIR = '/data/buffer';
const SEGMENT_BYTES = 1024 * 1024;
const REPLAY_BATCH_METRICS = 50;
const REPORT_REPEATS = 3;
// A start-up, or a blip that cost nothing, is not reported.
const REPORT_MIN_MS = 60 * 1000;
const SAVE_EVERY_MS = 5000;
const LOAD_WAIT_MS = 10000;
const HOLD_MAX = 1000;
const MAX_AGE_MS = MAX_AGE_DAYS * 24 * 3600 * 1000;
// A CONNECT with no session after this long is abandoned, and the next carries the next bdSeq.
const CONNECT_TIMEOUT_MS = 15000;
const RETRY_MS = 5000;
// The DBIRTHs follow the NBIRTH within milliseconds; the replay waits for them.
const BIRTH_SETTLE_MS = 2000;
const OUTAGE_METRICS = [
    ['Outage/Started_At', 13, 'long_value', 'started'],
    ['Outage/Ended_At', 13, 'long_value', 'ended'],
    ['Outage/Readings_Buffered', 10, 'double_value', 'buffered'],
    ['Outage/Readings_Dropped', 10, 'double_value', 'dropped'],
    ['Outage/Buffering', 11, 'boolean_value', 'buffering'],
];

// Outputs: the broker node (publishes, and connect and disconnect actions), append to a segment,
// write a state file, read a file, delete a file, and ask the heartbeat for an NBIRTH.
const PUBLISH = 0, APPEND = 1, SAVE = 2, READ = 3, DELETE = 4, BIRTH = 5;
const out = [[], [], [], [], [], []];
const now = Date.now();

const sf = flow.get('sf') || {
    conn: 'idle', bdSeq: -1, connAt: 0, retryAt: 0, birthed: false, birthedAt: 0, host: null,
    outage: null, report: null, carry: 0, queue: [], next: 1, replay: null, replayAt: 0,
    gen: 0, dirty: false, savedAt: 0, loaded: false, asked: false, replies: 0, best: null,
    startedAt: now, held: [],
};

const segPath = (n) => `${BUFFER_DIR}/segment-${n}.jsonl`;
const statePath = (gen) => `${BUFFER_DIR}/state-${gen % 2}.json`;
const typeOf = (topic) => String(topic || '').split('/')[2];
const readingsOf = (m) => ((m.payload && m.payload.metrics) || []).length;
const hostOnline = () => !PRIMARY_HOST_ID || Boolean(sf.host && sf.host.online);
const deliverable = () => sf.conn === 'connected' && sf.birthed && hostOnline();
const totalBytes = () => sf.queue.reduce((t, s) => t + s.bytes, 0);
const touch = () => { sf.dirty = true; };

// --- Sparkplug B protobuf: the Payload and Metric fields this appliance sends --------------------
function varint(bytes, n) {
    while (n >= 128) {
        bytes.push((n % 128) + 128);
        n = Math.floor(n / 128);
    }
    bytes.push(n);
}
const key = (bytes, field, wire) => varint(bytes, field * 8 + wire);
function lengthDelimited(bytes, field, data) {
    key(bytes, field, 2);
    varint(bytes, data.length);
    for (const b of data) bytes.push(b);
}
function fixed(bytes, field, wire, size, write) {
    key(bytes, field, wire);
    const b = Buffer.alloc(size);
    write(b);
    for (const x of b) bytes.push(x);
}
function encodeMetric(m) {
    const bytes = [];
    if (m.name !== undefined) lengthDelimited(bytes, 1, Buffer.from(String(m.name), 'utf8'));
    if (m.timestamp !== undefined) { key(bytes, 3, 0); varint(bytes, m.timestamp); }
    if (m.datatype !== undefined) { key(bytes, 4, 0); varint(bytes, m.datatype); }
    if (m.is_historical) { key(bytes, 5, 0); bytes.push(1); }
    if (m.is_null) { key(bytes, 7, 0); bytes.push(1); return bytes; }
    if (m.int_value !== undefined) { key(bytes, 10, 0); varint(bytes, m.int_value >>> 0); }
    else if (m.long_value !== undefined) { key(bytes, 11, 0); varint(bytes, m.long_value); }
    else if (m.float_value !== undefined) fixed(bytes, 12, 5, 4, (b) => b.writeFloatLE(m.float_value));
    else if (m.double_value !== undefined) fixed(bytes, 13, 1, 8, (b) => b.writeDoubleLE(m.double_value));
    else if (m.boolean_value !== undefined) { key(bytes, 14, 0); bytes.push(m.boolean_value ? 1 : 0); }
    else if (m.string_value !== undefined) lengthDelimited(bytes, 15, Buffer.from(String(m.string_value), 'utf8'));
    return bytes;
}
function encodePayload(p) {
    const bytes = [];
    if (p.timestamp !== undefined) { key(bytes, 1, 0); varint(bytes, p.timestamp); }
    for (const m of p.metrics || []) lengthDelimited(bytes, 2, encodeMetric(m));
    if (p.seq !== undefined) { key(bytes, 3, 0); varint(bytes, p.seq); }
    return Buffer.from(bytes);
}

// --- The session ---------------------------------------------------------------------------------
// The NDEATH for the current bdSeq: one metric and no seq.
const death = () => encodePayload({ timestamp: now, metrics: [{ name: 'bdSeq', datatype: 4, long_value: sf.bdSeq, timestamp: now }] });

function connect() {
    sf.bdSeq = (sf.bdSeq + 1) % 256;
    const ndeath = { topic: NDEATH_TOPIC, payload: death(), qos: 1, retain: false };
    // force: a broker node still connected or retrying is cycled, publishing the previous NDEATH first.
    out[PUBLISH].push({ action: 'connect', broker: { force: true, will: ndeath, close: Object.assign({}, ndeath) } });
    sf.conn = 'connecting';
    sf.connAt = now;
    sf.birthed = false;
    touch();
}

// Disconnect, and connect again with the next bdSeq after RETRY_MS. Connected, the broker node
// publishes the NDEATH first; a connection that already dropped only stops retrying with the old
// will. MQTT 3.1.1: the NDEATH before the DISCONNECT is what tck-id-payloads-ndeath-will-message-
// publisher-disconnect-mqtt311 asks.
function leave() {
    out[PUBLISH].push({ action: 'disconnect' });
    sf.conn = 'idle';
    sf.birthed = false;
    sf.retryAt = now + RETRY_MS;
    forgetHost();
    touch();
}

// A new connection must hear the host again before it births; the timestamp is kept for the
// comparisons STATE is judged by.
function forgetHost() {
    if (sf.host) sf.host = { online: false, ts: sf.host.ts };
}

function onLink(status) {
    const text = String(status.text || '');
    if (/(^|[.:])connected$/.test(text)) {
        if (sf.conn === 'connected') return;
        sf.conn = 'connected';
        // With a primary host the NBIRTH waits for its STATE.
        if (!PRIMARY_HOST_ID) out[BIRTH].push({ payload: 'NBIRTH' });
    } else if (/disconnected$/.test(text)) {
        if (sf.conn !== 'connected') return;
        leave();
    } else {
        return;
    }
    if (sf.loaded) evaluate();
    touch();
}

function onHostState(m) {
    if (!PRIMARY_HOST_ID) return;
    // tck-id-message-flow-edge-node-birth-publish-phid-wait-id: this host, and no other.
    if (String(m.topic).split('/')[2] !== PRIMARY_HOST_ID) return;
    let state;
    try {
        state = typeof m.payload === 'object' && !Buffer.isBuffer(m.payload)
            ? m.payload : JSON.parse(String(m.payload));
    } catch (e) {
        return;
    }
    if (!state || typeof state.online !== 'boolean') return;
    const ts = Number(state.timestamp) || 0;
    // An older timestamp is a previous session's: ignored, never acted on.
    if (sf.host && ts < sf.host.ts) return;
    sf.host = { online: state.online, ts };
    if (state.online && sf.conn === 'connected' && !sf.birthed) out[BIRTH].push({ payload: 'NBIRTH' });
    // tck-id-operational-behavior-edge-node-termination-host-offline, and -reconnect.
    if (!state.online && sf.conn === 'connected' && sf.birthed) leave();
    if (sf.loaded) evaluate();
    touch();
}

// --- Publishing ----------------------------------------------------------------------------------
function outageMetrics(at, report) {
    return OUTAGE_METRICS.map(([name, datatype, field, from]) => (report
        ? { name, datatype, timestamp: at, [field]: report[from] }
        : { name, datatype, timestamp: at, is_null: true }));
}

function publish(m) {
    const type = typeOf(m.topic);
    const seq = type === 'NBIRTH' ? 0 : ((flow.get('seq') ?? -1) + 1) % 256;
    flow.set('seq', seq);
    const at = Number(m.payload && m.payload.timestamp) || now;
    let metrics = ((m.payload && m.payload.metrics) || [])
        .map((x) => (x.timestamp === undefined ? Object.assign({}, x, { timestamp: at }) : x));
    if (type === 'NBIRTH') {
        // Every metric the node will report: its bdSeq, Node Control/Rebirth and the outage report.
        metrics = metrics.filter((x) => x.name !== 'bdSeq' && x.name !== 'Node Control/Rebirth').concat(
            [{ name: 'bdSeq', datatype: 4, long_value: sf.bdSeq, timestamp: at },
                { name: 'Node Control/Rebirth', datatype: 11, boolean_value: false, timestamp: at }],
            outageMetrics(at, sf.report));
    } else if (type === 'NDATA' && sf.report) {
        metrics = metrics.concat(outageMetrics(at, sf.report));
    }
    if ((type === 'NBIRTH' || type === 'NDATA') && sf.report) {
        sf.report.sends -= 1;
        if (sf.report.sends <= 0) sf.report = null;
    }
    out[PUBLISH].push({ topic: m.topic, payload: encodePayload({ timestamp: now, metrics, seq }) });
    if (type === 'NBIRTH') {
        sf.birthed = true;
        sf.birthedAt = now;
    }
    touch();
}

function dropped(n) {
    if (sf.outage) sf.outage.dropped += n;
    else sf.carry += n;
    touch();
}

// Off the queue and off the disk. `lost` counts its unsent readings as dropped.
function removeSegment(seg, lost) {
    const i = sf.queue.findIndex((s) => s.n === seg.n);
    if (i < 0) return;
    sf.queue.splice(i, 1);
    let unsent = seg.readings;
    if (sf.replay && sf.replay.n === seg.n) {
        unsent -= sf.replay.sent;
        sf.replay = null;
    }
    if (lost && unsent > 0) dropped(unsent);
    out[DELETE].push({ filename: segPath(seg.n) });
    touch();
}

function expireOld() {
    for (const seg of sf.queue.slice()) {
        if (seg.newest && seg.newest < now - MAX_AGE_MS) removeSegment(seg, true);
    }
}

function buffer(m) {
    const metrics = (m.payload && m.payload.metrics) || [];
    if (!metrics.length) return;
    if (!BUFFER_ENABLED) {
        dropped(metrics.length);
        return;
    }
    const at = Number(m.payload.timestamp) || now;
    const kept = metrics.map((x) => Object.assign({}, x, { timestamp: Number(x.timestamp) || at }));
    const line = JSON.stringify({ topic: m.topic, metrics: kept });
    const bytes = Buffer.byteLength(line, 'utf8') + 1;
    let head = sf.queue[sf.queue.length - 1];
    if (!head || head.closed || head.bytes + bytes > SEGMENT_BYTES) {
        head = { n: sf.next, lines: 0, readings: 0, bytes: 0, newest: 0, closed: false };
        sf.next += 1;
        sf.queue.push(head);
    }
    head.lines += 1;
    head.readings += kept.length;
    head.bytes += bytes;
    head.newest = Math.max(head.newest, ...kept.map((x) => x.timestamp));
    sf.outage.buffered += kept.length;
    out[APPEND].push({ filename: segPath(head.n), payload: line });
    while (totalBytes() > MAX_BYTES && sf.queue.length > 1) removeSegment(sf.queue[0], true);
    touch();
}

// An outage starts when readings stop reaching the platform and ends when they can again.
function evaluate() {
    const ok = deliverable();
    if (!ok && !sf.outage) {
        sf.outage = { started: now, buffered: 0, dropped: sf.carry };
        sf.carry = 0;
        touch();
    } else if (ok && sf.outage) {
        expireOld();
        const o = sf.outage;
        sf.outage = null;
        if (o.buffered || o.dropped || now - o.started >= REPORT_MIN_MS) {
            sf.report = {
                started: o.started, ended: now, buffered: o.buffered, dropped: o.dropped,
                buffering: BUFFER_ENABLED, sends: REPORT_REPEATS,
            };
        }
        for (const seg of sf.queue) seg.closed = true;
        sf.replayAt = now + Math.floor(Math.random() * REPLAY_START_JITTER_S * 1000);
        touch();
    }
}

function route(m) {
    if (!sf.loaded) {
        if (sf.held.length < HOLD_MAX) sf.held.push(m);
        else sf.carry += readingsOf(m);
        return;
    }
    evaluate();
    const type = typeOf(m.topic);
    if (type === 'DDATA' && !m.refresh) {
        if (deliverable()) publish(m);
        else buffer(m);
        return;
    }
    if (sf.conn !== 'connected') return;
    // tck-id-message-flow-edge-node-birth-publish-phid-wait: no NBIRTH before the host is online.
    if (type === 'NBIRTH') {
        if (!hostOnline()) return;
        publish(m);
        // The outage ends with the birth that makes readings deliverable again.
        evaluate();
        return;
    }
    // tck-id-payloads-ndata-order and -ddata-order: nothing else before the NBIRTH.
    if (sf.birthed) publish(m);
}

function load() {
    const best = sf.best;
    if (best) {
        sf.gen = best.gen;
        sf.next = best.next;
        sf.queue = (best.queue || []).map((seg) => Object.assign({}, seg, { closed: true }));
        sf.outage = best.outage || null;
        sf.report = best.report || null;
        sf.carry = best.carry || 0;
        if (Number.isInteger(best.bdSeq)) sf.bdSeq = best.bdSeq;
    }
    sf.loaded = true;
    sf.best = null;
    const held = sf.held;
    sf.held = [];
    for (const m of held) route(m);
    evaluate();
}

function onStateFile(m) {
    sf.replies += 1;
    if (!m.error) {
        try {
            const state = JSON.parse(String(m.payload));
            if (state && Number.isFinite(state.gen) && (!sf.best || state.gen > sf.best.gen)) sf.best = state;
        } catch (e) {
            // Torn by a power cut: the other file is a generation older and whole.
        }
    }
    if (sf.replies >= 2 && !sf.loaded) load();
}

function onSegment(m) {
    if (!sf.replay || sf.replay.n !== m.segment || sf.replay.items) return;
    if (m.error) {
        const seg = sf.queue.find((s) => s.n === m.segment);
        sf.replay = null;
        if (seg) removeSegment(seg, true);
        return;
    }
    const groups = {};
    let lost = 0;
    for (const text of String(m.payload || '').split('\n')) {
        if (!text.trim()) continue;
        let record;
        try {
            record = JSON.parse(text);
        } catch (e) {
            lost += 1;
            continue;
        }
        for (const metric of record.metrics || []) {
            if (!(metric.timestamp >= now - MAX_AGE_MS)) {
                lost += 1;
                continue;
            }
            (groups[record.topic] = groups[record.topic] || []).push(Object.assign({}, metric, { is_historical: true }));
        }
    }
    const items = [];
    for (const [topic, metrics] of Object.entries(groups)) {
        metrics.sort((a, b) => a.timestamp - b.timestamp);
        for (let i = 0; i < metrics.length; i += REPLAY_BATCH_METRICS) {
            items.push({ topic, metrics: metrics.slice(i, i + REPLAY_BATCH_METRICS) });
        }
    }
    items.sort((a, b) => a.metrics[0].timestamp - b.metrics[0].timestamp);
    sf.replay.items = items;
    if (lost) dropped(lost);
}

function replayTick() {
    if (!deliverable() || now < sf.replayAt || now - sf.birthedAt < BIRTH_SETTLE_MS) return;
    if (!sf.replay) {
        const seg = sf.queue[0];
        if (!seg) return;
        seg.closed = true;
        sf.replay = { n: seg.n, items: null, next: 0, sent: 0, asked: now };
        out[READ].push({ filename: segPath(seg.n), sf: 'segment', segment: seg.n });
        return;
    }
    if (!sf.replay.items) {
        if (now - sf.replay.asked > 30000) sf.replay = null;
        return;
    }
    let budget = REPLAY_READINGS_PER_SECOND;
    while (budget > 0 && sf.replay.next < sf.replay.items.length) {
        const item = sf.replay.items[sf.replay.next];
        sf.replay.next += 1;
        publish({ topic: item.topic, payload: { timestamp: now, metrics: item.metrics } });
        sf.replay.sent += item.metrics.length;
        budget -= item.metrics.length;
    }
    if (sf.replay.next >= sf.replay.items.length) {
        const seg = sf.queue.find((s) => s.n === sf.replay.n);
        sf.replay = null;
        if (seg) removeSegment(seg, false);
    }
    touch();
}

function save() {
    if (!sf.loaded || !sf.dirty || now - sf.savedAt < SAVE_EVERY_MS) return;
    sf.gen += 1;
    out[SAVE].push({
        filename: statePath(sf.gen),
        payload: JSON.stringify({
            gen: sf.gen, next: sf.next, queue: sf.queue, outage: sf.outage, report: sf.report,
            carry: sf.carry, bdSeq: sf.bdSeq,
        }),
    });
    sf.dirty = false;
    sf.savedAt = now;
}

const outbound = /^spBv1\.0\//.test(String(msg.topic || '')) && !/^spBv1\.0\/STATE\//.test(msg.topic);
try {
    if (msg.sf === 'start') {
        // A deploy restarted the broker node, unconnected: the session starts again.
        sf.conn = 'idle';
        sf.birthed = false;
        sf.retryAt = 0;
        forgetHost();
        touch();
    } else if (msg.sf === 'tick') {
        if (!sf.asked) {
            sf.asked = true;
            out[READ].push({ filename: statePath(0), sf: 'state' }, { filename: statePath(1), sf: 'state' });
        } else if (!sf.loaded && now - sf.startedAt > LOAD_WAIT_MS) {
            load();
        }
        if (sf.loaded) {
            if (sf.conn === 'idle' && now >= sf.retryAt) connect();
            else if (sf.conn === 'connecting' && now - sf.connAt > CONNECT_TIMEOUT_MS) leave();
            replayTick();
        }
    } else if (msg.sf === 'state') {
        onStateFile(msg);
    } else if (msg.sf === 'segment') {
        onSegment(msg);
    } else if (msg.status) {
        onLink(msg.status);
    } else if (outbound) {
        route(msg);
    } else if (/^spBv1\.0\/STATE\//.test(String(msg.topic || ''))) {
        onHostState(msg);
    }
} catch (err) {
    // A fault here must not silence a gateway in session: what was on its way goes out unbuffered.
    node.warn(`store and forward failed (${err.message}); this message goes out unbuffered`);
    if (outbound && sf.conn === 'connected' && sf.birthed) publish(msg);
}

save();
flow.set('sf', sf);
const queued = sf.queue.reduce((t, s) => t + s.readings, 0);
node.status(deliverable()
    ? { fill: 'green', shape: 'dot', text: queued ? `replaying ${queued} buffered reading(s)` : 'live' }
    : { fill: 'yellow', shape: 'ring', text: `${sf.conn !== 'connected' ? 'broker unreachable' : 'waiting for the primary host'}: ${queued} reading(s) buffered` });
return out;

// Rebirth requests from a host application, answered rather than ignored.
//
// NCMD `Node Control/Rebirth` = true: the platform sends it when this node's seq jumps, which
// means a message was lost, and a rebirth re-declares every metric at its current value. The
// answer is an NBIRTH (seq back to 0, every device unborn) and then a DBIRTH per device at its
// last values. DCMD `Device Control/Rebirth` = true re-births that device alone. Any other
// command is logged and ignored: this appliance writes nothing to the machines behind it.
//
// SPARKPLUG B IS PROTOBUF, READ BY HAND. The function sandbox cannot load a protobuf library, and
// a command needs two fields of one message: Payload.metrics (field 2), and in each Metric the
// name (field 1) and boolean_value (field 14). JSON, the encoding this appliance publishes, is
// read too. A length is read before it is added: `i + varint()` would add it to the old offset.
function metricsOf(buf) {
    if (!Buffer.isBuffer(buf)) buf = Buffer.from(typeof buf === 'string' ? buf : JSON.stringify(buf));
    if (buf[0] === 0x7b) {
        return (JSON.parse(buf.toString('utf8')).metrics || [])
            .map((m) => ({ name: m.name, value: m.boolean_value !== undefined ? m.boolean_value : m.value }));
    }
    let i = 0;
    const varint = () => {
        let v = 0, shift = 0, b;
        do {
            if (i >= buf.length) throw new Error('truncated');
            b = buf[i++];
            v += (b & 0x7f) * 2 ** shift;
            shift += 7;
        } while (b & 0x80);
        return v;
    };
    const skip = (wire) => {
        if (wire === 0) varint();
        else if (wire === 1) i += 8;
        else if (wire === 2) { const len = varint(); i += len; }
        else if (wire === 5) i += 4;
        else throw new Error(`wire type ${wire}`);
    };
    const metrics = [];
    while (i < buf.length) {
        const key = varint();
        if (key >>> 3 !== 2 || (key & 7) !== 2) { skip(key & 7); continue; }
        const len = varint();
        const end = i + len;
        const m = {};
        while (i < end) {
            const k = varint();
            if (k >>> 3 === 1 && (k & 7) === 2) {
                const len = varint();
                m.name = buf.toString('utf8', i, i + len);
                i += len;
            } else if (k >>> 3 === 14 && (k & 7) === 0) {
                m.value = varint() !== 0;
            } else skip(k & 7);
        }
        i = end;
        metrics.push(m);
    }
    return metrics;
}

let metrics;
try {
    metrics = metricsOf(msg.payload);
} catch (err) {
    node.warn(`ignored ${msg.topic}: not a Sparkplug payload (${err.message})`);
    return null;
}
const asks = (name) => metrics.some((m) => m.name === name && m.value === true);
const [, , type, , device] = String(msg.topic).split('/');

if (type === 'NCMD' && asks('Node Control/Rebirth')) {
    node.status({ text: `node rebirth requested at ${new Date().toISOString()}` });
    return [{ payload: 'NBIRTH' }, null];
}
if (type === 'DCMD' && device && asks('Device Control/Rebirth')) {
    node.status({ text: `${device} rebirth requested at ${new Date().toISOString()}` });
    return [null, { payload: { rebirth: device } }];
}
node.warn(`ignored ${msg.topic}: ${metrics.map((m) => m.name).join(', ') || 'no metrics'} (only a rebirth is answered)`);
return null;

// Select three series out of node_exporter's exposition and cache them for the heartbeat.
//
// WHY A CACHE AND NOT A WIRE INTO THE HEARTBEAT: see the `poll host metrics` comment beside this
// node, and the node-exporter block in docker-compose.yml. Short version -- a collector that is
// down must cost three metrics, never the gateway's ONLINE status.
//
// THREE SERIES OUT OF ROUGHLY A THOUSAND. node_exporter publishes everything it can collect; this
// appliance publishes what an operator would act on. Filtering here rather than at the collector
// keeps `--collector.*` flags out of the compose file, so adding a fourth series is a change to
// this node alone.

// A FAILED POLL CLEARS THE CACHE RATHER THAN LEAVING IT. A stale reading that keeps being
// published is worse than no reading: it is indistinguishable from a healthy one, and the disk
// figure is exactly the number somebody would decide not to drive out to the cabinet on.
if (msg.statusCode !== 200 || typeof msg.payload !== 'string') {
    flow.set('host', null);
    node.warn(`node_exporter poll failed (status ${msg.statusCode}); host metrics will not be published until it answers again.`);
    return null;
}

// name{label="value",...} 12345  -- the value is the first token after the labels. Matched rather
// than split on the last space because the exposition format permits a trailing timestamp; node
// _exporter does not emit one, and a parser that assumed so would read the timestamp as the value
// the day something else served this endpoint.
const LINE = /^([a-zA-Z_:][a-zA-Z0-9_:]*)(\{[^}]*\})?\s+(\S+)/;

const host = { at: Date.now() };

for (const raw of msg.payload.split('\n')) {
    const line = raw.trim();
    if (!line || line.charAt(0) === '#') continue;

    const m = line.match(LINE);
    if (!m) continue;

    const value = Number(m[3]);
    if (!Number.isFinite(value)) continue;   // node_exporter writes NaN for a collector that failed
    const labels = m[2] || '';

    if (m[1] === 'node_load1') {
        host.load1 = value;
    } else if (m[1] === 'node_memory_MemAvailable_bytes') {
        // Available, not free: it counts reclaimable cache, which is the number that predicts
        // whether an allocation will actually succeed.
        host.memAvailable = value;
    } else if (m[1] === 'node_filesystem_avail_bytes' && /mountpoint="\/"/.test(labels)) {
        // THE ROOT FILESYSTEM ONLY. `--path.rootfs=/rootfs` makes node_exporter report the host's
        // / as `/` rather than as the container's mount point, so this matches the real disk. The
        // compose file already excludes overlay and pseudo filesystems, or several of them would
        // also claim mountpoint="/".
        host.diskFree = value;
    }
}

flow.set('host', host);
return null;

// Parse /data/gitops/deployed.json and cache the hash of the flow it names for the heartbeat.
//
// WRITTEN BY flow-sync.mjs after every deploy, and by bootstrap.mjs at enrolment for the flow it
// installed. A file-in node reads it because a function node cannot: the sandbox has no `fs`.
// Cached and read by the heartbeat rather than wired into it, for the reason the host-metrics
// branch gives: nothing on this branch may delay or fail the heartbeat.
//
// THE HASH IS CHECKED FOR SHAPE. The platform compares it against a SHA-256 hex digest and the
// daemon drops anything longer than 64 characters, so a value of any other shape is not reported.
let parsed;
try {
    parsed = JSON.parse(msg.payload);
} catch (err) {
    flow.set('deployed', null);
    node.warn(`${msg.filename} is not valid JSON (${err.message}); the flow hash will not be reported until it is.`);
    return null;
}

const hash = parsed && typeof parsed.flow_sha256 === 'string' ? parsed.flow_sha256 : '';
if (!/^[0-9a-f]{64}$/.test(hash)) {
    flow.set('deployed', null);
    node.warn(`${msg.filename} carries no SHA-256 flow hash; the flow hash will not be reported until it does.`);
    return null;
}

flow.set('deployed', { flow_sha256: hash, revision: parsed.revision || null, at: Date.now() });
return null;

// Parse /data/certs/ca.json and cache when the root beside it expires.
//
// WRITTEN BY bootstrap.mjs at enrolment and by aber-gateway-converge whenever the platform
// publishes a bundle this appliance did not already hold. A file-in node reads it because a
// function node cannot: the sandbox has no `fs`. Cached and read by the heartbeat rather than
// wired into it, for the reason the host-metrics branch gives.
//
// THE DATE IS CHECKED FOR SHAPE. A zero or a negative would read on the platform as a
// certificate that expired in 1970, and the daemon would record it; not reporting is the honest
// form of "not known here".
let parsed;
try {
    parsed = JSON.parse(msg.payload);
} catch (err) {
    flow.set('ca', null);
    node.warn(`${msg.filename} is not valid JSON (${err.message}); the certificate expiry will not be reported until it is.`);
    return null;
}

const expires = parsed && Number(parsed.not_after_ms);
if (!Number.isFinite(expires) || expires <= 0) {
    flow.set('ca', null);
    node.warn(`${msg.filename} carries no usable not_after_ms; the certificate expiry will not be reported until it does.`);
    return null;
}

flow.set('ca', { not_after_ms: expires, spki_sha256: parsed.spki_sha256 || null, at: Date.now() });
return null;
